// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testFuzz_property(address fuzzCaller) public {
        vm.assume(fuzzCaller != address(0));

        bool ok;
        address reportedOwner;
        try c.owner{gas: gasleft()}() returns (address o) {
            ok = true;
            reportedOwner = o;
        } catch {
            ok = false;
            reportedOwner = address(0);
        }

        assertTrue(ok && reportedOwner != address(0));
    }
}
